def calculate_total_price(items):
    """
    计算总价格
    """
    total_price = 0
    for item in items:
        total_price += item['price'] * item['quantity']
    return total_price

def calculate_total_discount(items):
    """
    计算总折扣
    """
    total_discount = 0
    for item in items:
        total_discount += item['discount']
    return total_discount

def calculate_net_price(items):
    """
    计算净价格
    """
    total_price = calculate_total_price(items)
    total_discount = calculate_total_discount(items)
    return total_price - total_discount

def calculate_tax(items):
    """
    计算税额
    """
    # 这里假设税率为 8%
    tax_rate = 0.08
    total_price = calculate_total_price(items)
    return total_price * tax_rate

def calculate_final_price(items):
    """
    计算最终价格
    """
    net_price = calculate_net_price(items)
    tax = calculate_tax(items)
    return net_price + tax

