import unittest

class TestCalculator(unittest.TestCase):
    def test_calculate_total_price(self):
        items = [
            {'price': 10, 'quantity': 2},
            {'price': 20, 'quantity': 3}
        ]
        self.assertEqual(calculate_total_price(items), 10*2 + 20*3)

    def test_calculate_total_discount(self):
        items = [
            {'price': 10, 'quantity': 2, 'discount': 5},
            {'price': 20, 'quantity': 3, 'discount': 10}
        ]
        self.assertEqual(calculate_total_discount(items), 5 + 10)

    def test_calculate_net_price(self):
        items = [
            {'price': 10, 'quantity': 2, 'discount': 5},
            {'price': 20, 'quantity': 3, 'discount': 10}
        ]
        self.assertEqual(calculate_net_price(items), (10*2 + 20*3) - (5 + 10))

    def test_calculate_tax(self):
        items = [
            {'price': 10, 'quantity': 2},
            {'price': 20, 'quantity': 3}
        ]
        self.assertEqual(calculate_tax(items), (10*2 + 20*3) * 0.08)

    def test_calculate_final_price(self):
        items = [
            {'price': 10, 'quantity': 2},
            {'price': 20, 'quantity': 3}
        ]
        self.assertEqual(calculate_final_price(items), (10*2 + 20*3) + ((10*2 + 20*3) * 0.08))

if __name__ == '__main__':
    unittest.main()
